import{z as B,x as s,o as e,c as d,q as A,j as i,D as E,d as t,s as o,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"增长-通胀象限","description":"","frontmatter":{"title":"增长-通胀象限","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-growth-inflation-quadrant.md","filePath":"quant/mac-growth-inflation-quadrant.md","lastUpdated":1791063341000}'),p={name:"quant/mac-growth-inflation-quadrant.md"};function m(D,a,c,h,u,C){const n=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=A('<h1 id="增长-通胀象限" tabindex="-1">增长-通胀象限 <a class="header-anchor" href="#增长-通胀象限" aria-label="Permalink to &quot;增长-通胀象限&quot;">​</a></h1><div class="epigraph"><p>把宏观压成两个轴会丢信息，但不压成轴就什么都做不了：增长定分子的方向，通胀定贴现率的脾气。</p><footer>—— 据 Fama &amp; French, Journal of Financial Economics, 1989 与美林投资时钟报告（2004）整理</footer></div><p><a href="/quant/mac-regime-identification">上一课</a>把宏观状态变成滤波概率与转移矩阵，并约定回测只能用实时口径。本课把最常用的二维 regime 展开：增长与通胀。同是「状态转坏」，通胀上行与通胀下行对应的资产排序相反，一维识别在这里失效。象限给每个状态格配上相对赢家与可交易代理，后课的战术配置直接消费这张映射表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一维 regime 不够。增长下行的两种走法——通胀同升（滞胀）与通胀同落（衰退）——在大类资产上的排序相反：债券在后者常是当年的最佳资产，在前者几乎垫底。把两种情形合并成一个「坏状态」，仓位映射必然错一半。</p><p><span class="marginnote">常见误区：以为「经济变坏就买债券」。增长下行若伴随通胀上行（滞胀），债券几乎垫底，最稳的是现金；只有通胀一起回落的「衰退格」才是债券的天下。先看通胀轴的符号，再谈买什么。</span>缺口是把增长意外与通胀意外各取一轴，问每格里谁是相对赢家，以及用什么工具表达——不是买「资产名」，是买久期、贝塔、商品或通胀挂钩腿。</p><h3 id="意外进定价-水平只是背景" tabindex="-1">意外进定价，水平只是背景 <a class="header-anchor" href="#意外进定价-水平只是背景" aria-label="Permalink to &quot;意外进定价，水平只是背景&quot;">​</a></h3><p><a href="/quant/macro-factor-set">宏观因子</a>已立了口径：进入定价的是意外而非水平。操作化：增长轴用 PMI 或工业增加值环比动量对共识的偏离，通胀轴用 CPI 环比与盈亏平衡通胀率的边际变化。两轴各自标准化后划四格：复苏（增长正、通胀负）、过热（双正）、滞胀（增长负、通胀正）、衰退（双负）。</p><p><span class="marginnote">股债相关性的符号在 1990 年代末前后翻转：此前通胀冲击主导时股债同跌，此后增长冲击主导时债券成了股票的对冲。把 2000 年后的相关性外推回 1970 年代，会高估 60/40 组合在滞胀里的保护。</span></p><p><span class="marginnote">「意外进定价，水平只是背景」举例：CPI 同比 3% 这个数字本身不构成信号；本月公布的 3% 高于市场共识的 2.6%，这 0.4 个百分点的差才是行情的来源——共识早就被价格消化了，动的只有意外。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>映射表按贴现率与盈利的两分法填：复苏格里盈利修复而贴现率未动，股票贝塔最好；过热格里需求拉动通胀，商品与通胀挂钩债占优；滞胀格里估值与盈利双杀，现金的实际收益最稳；衰退格里通胀回落压贴现率，久期最好。表达全部落在可交易工具上：衰退格买国债期货或现券拉久期，复苏格加股指贝塔，过热与滞胀格用商品期货与挂钩债调整，而不是按叙事买板块。</p>',12)),(e(),i(l,null,{default:E(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%A2%9E%E9%95%BF%E6%84%8F%E5%A4%96%22%5D%20--%3E%20Q%7B%22%E8%B1%A1%E9%99%90%E5%88%A4%E5%AE%9A%22%7D%0A%20%20I%5B%22%E9%80%9A%E8%83%80%E6%84%8F%E5%A4%96%22%5D%20--%3E%20Q%0A%20%20Q%20--%3E%7C%E5%A4%8D%E8%8B%8F%7C%20EQ%5B%22%E8%82%A1%E7%A5%A8%E8%B4%9D%E5%A1%94%22%5D%0A%20%20Q%20--%3E%7C%E8%BF%87%E7%83%AD%7C%20CM%5B%22%E5%95%86%E5%93%81%E4%B8%8E%E6%8C%82%E9%92%A9%E5%80%BA%22%5D%0A%20%20Q%20--%3E%7C%E8%A1%B0%E9%80%80%7C%20DU%5B%22%E4%B9%85%E6%9C%9F%22%5D%0A%20%20Q%20--%3E%7C%E6%BB%9E%E8%83%80%7C%20CA%5B%22%E7%8E%B0%E9%87%91%22%5D%0A%20%20EQ%20--%3E%20T%5B%22%E6%88%98%E6%9C%AF%E5%81%8F%E7%A6%BB%EF%BC%88%E5%90%8E%E8%AF%BE%EF%BC%89%22%5D%0A%20%20CM%20--%3E%20T%0A%20%20DU%20--%3E%20T%0A%20%20CA%20--%3E%20T%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"排序的机制是分子与分母的赛跑：债券现金流固定，通胀意外升即贴现率升，债券必输；股票的分子随增长修复，只有通胀意外同时抬贴现率时才输——复苏与过热对股票的分野全在通胀腿。相关性本身是象限的函数：通胀主导定价时股债相关性为正，增长主导定价时为负，60/40 的保护只在后一类象限成立。象限表因此同时是收益表与风险表：换格时不仅换赢家，还换分散结构，风险预算要跟着换格走，不能只挪收益敞口。",-1)),(e(),i(l,null,{default:E(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20GI%5B%22%E9%80%9A%E8%83%80%E6%84%8F%E5%A4%96%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20DR%5B%22%E8%B4%B4%E7%8E%B0%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20GR%5B%22%E5%A2%9E%E9%95%BF%E6%84%8F%E5%A4%96%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20EPS%5B%22%E7%9B%88%E5%88%A9%E9%A2%84%E6%9C%9F%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20DR%20--%3E%20B%5B%22%E5%80%BA%E5%88%B8%3A%20%E7%8E%B0%E9%87%91%E6%B5%81%E5%9B%BA%E5%AE%9A%20%E2%86%92%20%E5%BF%85%E8%BE%93%22%5D%0A%20%20EPS%20--%3E%20S1%5B%22%E8%82%A1%E7%A5%A8%E5%88%86%E5%AD%90%E6%94%B9%E5%96%84%22%5D%0A%20%20DR%20--%3E%20S2%5B%22%E8%82%A1%E7%A5%A8%E5%88%86%E6%AF%8D%E5%90%8C%E6%97%B6%E5%8F%97%E5%8E%8B%22%5D%0A%20%20S1%20--%3E%20D%7B%22%E4%B8%A4%E8%82%A1%E5%8A%9B%E9%87%8F%E8%B0%81%E8%B5%A2%22%7D%0A%20%20S2%20--%3E%20D%0A%20%20D%20--%3E%7C%22%E9%80%9A%E8%83%80%E8%85%BF%E6%B8%A9%E5%92%8C%22%7C%20W%5B%22%E5%A4%8D%E8%8B%8F%E6%A0%BC%3A%20%E8%82%A1%E7%A5%A8%E5%8D%A0%E4%BC%98%22%5D%0A%20%20D%20--%3E%7C%22%E9%80%9A%E8%83%80%E8%85%BF%E8%BF%87%E7%83%AD%22%7C%20L%5B%22%E8%BF%87%E7%83%AD%E6%A0%BC%3A%20%E5%95%86%E5%93%81%E5%8D%A0%E4%BC%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">「分子与分母的赛跑」用房子打比方：股票像一栋能涨租金的房子（分子=租金，分母=折现率），债券像一笔租金写死的租约。利率一升两者都掉价，但债券的现金流没有回旋，股票还能靠生意变好找补回来——这就是两轴必须分开看的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>四格把两个连续量硬切，边界抖动时仓位在相邻格间翻转，映射要按概率带渐进（上一课的口径）。时钟的样本以美国战后至 2000 年代为主，格序依赖央行的反应函数：通胀目标制确立前后的格序不同，搬到别的经济体要重新验证。象限当择时触发器会过拟合，当风险预算偏置更稳。也不把「现金」字面化：滞胀格里持币的意思是缩短久期、压低贝塔，不是囤钞票。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>增长与通胀各取意外一轴成四格；同是「变坏」，滞胀与衰退的资产排序相反。</li><li>每格配相对赢家与可交易代理：复苏贝塔、过热商品、滞胀缩久期压贝塔、衰退买久期。</li><li>股债相关性的符号随象限变，60/40 的保护只在通胀意外为负时成立。</li><li>格序依赖央行反应函数与样本期，跨经济体使用要重新验证。</li><li>出处：Fama &amp; French, JFE, 1989；美林投资时钟（2004）的叙事框架；意外口径见<a href="/quant/macro-factor-set">宏观因子</a>。</li></ul>',5))])}const _=B(p,[["render",m]]);export{F as __pageData,_ as default};
